messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Red vs Blue 3D Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const RACE_DURATION = 6.0; // Seconds for the full race
    const TRACK_LENGTH = 200;
    const FINISH_LINE_POS = 80;

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // Sky blue
    scene.fog = new THREE.Fog(0x87CEEB, 50, 250);

    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 500);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1);
    dirLight.position.set(50, 100, 50);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 2048;
    dirLight.shadow.mapSize.height = 2048;
    dirLight.shadow.camera.near = 0.5;
    dirLight.shadow.camera.far = 500;
    dirLight.shadow.camera.left = -100;
    dirLight.shadow.camera.right = 100;
    dirLight.shadow.camera.top = 100;
    dirLight.shadow.camera.bottom = -100;
    scene.add(dirLight);

    // --- Environment ---
    // Ground
    const planeGeometry = new THREE.PlaneGeometry(400, 500);
    const planeMaterial = new THREE.MeshStandardMaterial({ color: 0x228B22 }); // Forest Green
    const plane = new THREE.Mesh(planeGeometry, planeMaterial);
    plane.rotation.x = -Math.PI / 2;
    plane.position.z = 0;
    plane.receiveShadow = true;
    scene.add(plane);

    // Track
    const trackGeo = new THREE.PlaneGeometry(20, 500);
    const trackMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
    const track = new THREE.Mesh(trackGeo, trackMat);
    track.rotation.x = -Math.PI / 2;
    track.position.y = 0.05; // Slightly above grass
    track.receiveShadow = true;
    scene.add(track);

    // Finish Line
    const finishGeo = new THREE.PlaneGeometry(20, 4);
    const finishMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
    // Create a simple checkerboard pattern using canvas texture logic implicitly or just simple white/black stripes
    const finishCanvas = document.createElement('canvas');
    finishCanvas.width = 64; finishCanvas.height = 64;
    const ctx = finishCanvas.getContext('2d');
    ctx.fillStyle = '#FFF'; ctx.fillRect(0,0,64,64);
    ctx.fillStyle = '#000'; 
    ctx.fillRect(0,0,32,32); ctx.fillRect(32,32,32,32);
    const finishTex = new THREE.CanvasTexture(finishCanvas);
    finishTex.wrapS = THREE.RepeatWrapping;
    finishTex.wrapT = THREE.RepeatWrapping;
    finishTex.repeat.set(10, 2);
    finishMat.map = finishTex;

    const finishLine = new THREE.Mesh(finishGeo, finishMat);
    finishLine.rotation.x = -Math.PI / 2;
    finishLine.position.set(0, 0.06, FINISH_LINE_POS);
    scene.add(finishLine);

    // Finish Line Posts
    const postGeo = new THREE.CylinderGeometry(0.5, 0.5, 10);
    const postMat = new THREE.MeshStandardMaterial({ color: 0xdddddd });
    const postL = new THREE.Mesh(postGeo, postMat);
    postL.position.set(-10, 5, FINISH_LINE_POS);
    scene.add(postL);
    const postR = new THREE.Mesh(postGeo, postMat);
    postR.position.set(10, 5, FINISH_LINE_POS);
    scene.add(postR);

    // --- Car Factory ---
    function createCar(color) {
        const carGroup = new THREE.Group();

        // Chassis
        const chassisGeo = new THREE.BoxGeometry(2, 1, 4);
        const chassisMat = new THREE.MeshStandardMaterial({ color: color });
        const chassis = new THREE.Mesh(chassisGeo, chassisMat);
        chassis.position.y = 1;
        chassis.castShadow = true;
        carGroup.add(chassis);

        // Cabin
        const cabinGeo = new THREE.BoxGeometry(1.8, 0.8, 2);
        const cabinMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
        const cabin = new THREE.Mesh(cabinGeo, cabinMat);
        cabin.position.y = 1.8;
        cabin.position.z = -0.2;
        cabin.castShadow = true;
        carGroup.add(cabin);

        // Wheels
        const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.4, 16);
        const wheelMat = new THREE.MeshStandardMaterial({ color: 0x000000 });

        const positions = [
            { x: -1.1, z: 1.2 }, { x: 1.1, z: 1.2 },
            { x: -1.1, z: -1.2 }, { x: 1.1, z: -1.2 }
        ];

        positions.forEach(pos => {
            const wheel = new THREE.Mesh(wheelGeo, wheelMat);
            wheel.rotation.z = Math.PI / 2;
            wheel.position.set(pos.x, 0.4, pos.z);
            wheel.castShadow = true;
            carGroup.add(wheel);
        });

        return carGroup;
    }

    const blueCar = createCar(0x0000FF); // Bright Blue
    const redCar = createCar(0xFF0000);  // Bright Red

    // Initial Positions (Start line is at Z = -80)
    blueCar.position.set(-4, 0, -80);
    redCar.position.set(4, 0, -80);

    scene.add(blueCar);
    scene.add(redCar);

    // --- Animation Logic ---
    const clock = new THREE.Clock();

    // Helper for Easing
    // t: current time, b: start value, c: change in value, d: duration
    function easeInOutQuad(t, b, c, d) {
        t /= d / 2;
        if (t < 1) return c / 2 * t * t + b;
        t--;
        return -c / 2 * (t * (t - 2) - 1) + b;
    }

    // Helper for custom racing logic
    function getCarZ(carType, progress) {
        // progress is 0 to 1
        const startZ = -80;
        const totalDist = 180; // -80 to 100

        if (carType === 'blue') {
            // Blue starts fast, slows down
            // 0-40%: very fast
            // 40-100%: steady/slow
            if (progress < 0.4) {
                // Cover 60% of distance in first 40% of time
                const localProg = progress / 0.4;
                return startZ + (totalDist * 0.6) * easeInOutQuad(localProg, 0, 1, 1);
            } else {
                // Cover remaining 40% distance in last 60% of time
                const localProg = (progress - 0.4) / 0.6;
                return (startZ + totalDist * 0.6) + (totalDist * 0.4) * easeInOutQuad(localProg, 0, 1, 1);
            }
        } else {
            // Red starts slow, accelerates
            // 0-30%: slow
            // 30-100%: very fast
            if (progress < 0.3) {
                // Cover 20% of distance in first 30% of time
                const localProg = progress / 0.3;
                return startZ + (totalDist * 0.2) * easeInOutQuad(localProg, 0, 1, 1);
            } else {
                // Cover remaining 80% distance in last 70% of time
                const localProg = (progress - 0.3) / 0.7;
                return (startZ + totalDist * 0.2) + (totalDist * 0.8) * easeInOutQuad(localProg, 0, 1, 1);
            }
        }
    }

    function animate() {
        requestAnimationFrame(animate);

        const elapsed = clock.getElapsedTime();
        let progress = (elapsed % RACE_DURATION) / RACE_DURATION;

        // Calculate positions
        const blueZ = getCarZ('blue', progress);
        const redZ = getCarZ('red', progress);

        blueCar.position.z = blueZ;
        redCar.position.z = redZ;

        // Add some wheel rotation for effect
        const wheelSpeed = 0.5;
        blueCar.children.forEach(c => {
            if(c.geometry.type === 'CylinderGeometry') c.rotation.x += wheelSpeed;
        });
        redCar.children.forEach(c => {
            if(c.geometry.type === 'CylinderGeometry') c.rotation.x += wheelSpeed;
        });

        // Camera Logic
        // Find the leading car (highest Z)
        const leadZ = Math.max(blueZ, redZ);
        const trailZ = Math.min(blueZ, redZ);

        // Target camera position: behind the midpoint of the two cars
        const midZ = (leadZ + trailZ) / 2;

        // Camera follows, but stays behind the cars
        // We want to see them driving away, so camera Z is less than car Z
        // However, standard coord system: +Z is "forward" in this setup? 
        // Wait, in Three.js standard, -Z is usually into the screen.
        // Let's look at the setup: Start -80, Finish 80. So +Z is forward.
        // Camera needs to be at a Z < car Z to look down the +Z axis?
        // No, if camera is at Z=0 looking at Z=10, it looks +Z direction.
        // If cars are at Z=50, camera should be at Z=40 looking at Z=60.

        // Let's position camera behind the cars (lower Z) looking forward (+Z)
        // Or position camera in front looking back? 
        // "Race toward a visible finish line" usually implies seeing the back of the cars.
        // Cars move -80 -> 80. Camera should be at Z < CarZ.

        // Dynamic Camera Position
        const camDist = 25; // Distance behind the midpoint
        const camHeight = 12;
        const camOffsetX = 0; // Centered between lanes

        // Smoothly interpolate camera position
        // We want the camera to be behind the cars.
        // If cars are at 50, camera at 25.

        // Let's use a target that lags slightly behind the midpoint to ensure both are in view
        // If they are close together, camera is close. If spread out, camera is further back.
        const distBetweenCars = Math.abs(leadZ - trailZ);
        const lookAhead = 30;

        // Camera Position
        // We place the camera behind the *trailing* car to ensure both are visible?
        // Or behind the midpoint. Let's try behind the midpoint but looking ahead.

        const targetCamZ = midZ - 20 - (distBetweenCars / 2);
        // Clamp camera so it doesn't go too far back or too far forward
        // Actually, simpler approach: Camera follows the leading car but looks back?
        // No, seeing the back of the cars is more dramatic for a race.

        // Let's make the camera position relative to the midpoint, but look at the leader
        const currentCamZ = targetCamZ;

        // Smooth camera movement
        camera.position.z += (currentCamZ - camera.position.z) * 0.1;
        camera.position.x += (0 - camera.position.x) * 0.1; // Center X
        camera.position.y += (camHeight - camera.position.y) * 0.1;

        // Look at a point ahead of the midpoint
        camera.lookAt(0, 2, midZ + lookAhead);

        renderer.render(scene, camera);
    }

    // Handle Resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    animate();
</script>
</body>
</html>
```
